import{d as a,S as t,i as n,l as o}from"./chunks/framework.CY2TYXqZ.js";const u=JSON.parse('{"title":"Need to Know","description":"A black-box engagement against FileHub, a file-sharing service whose product page promises that a file uploaded by one account is readable only by that account.","frontmatter":{"title":"Need to Know","number":1,"layout":"challenge","difficulty":"easy","category":"web","backend":"fastapi","app":"app.py","packages":[],"tools":["browser","network","repeater","code"],"source_visible":false,"date":"2026-04-02T08:54:17.674Z","tags":["idor","access-control","fastapi","sqlite"],"description":"A black-box engagement against FileHub, a file-sharing service whose product page promises that a file uploaded by one account is readable only by that account.","wasmModule":"/challenge/door-is-open/runtime.wasm","markdownBody":"\\n# Need to Know\\n\\n**Client:** FileHub, a file-sharing service used by small teams.\\n**Engagement:** Black-box assessment of the FileHub web application.\\n\\n## Scope\\n\\nIn scope: the FileHub application served at this origin and every HTTP endpoint\\nit exposes.\\n\\nFileHub has issued you one account for this engagement — username `guest`,\\npassword `guest`. It is an ordinary account with no elevated rights, and it is\\nthe only credential you have been given.\\n\\nOut of scope: the hosting platform, other engagements, and denial of service.\\n\\n## Rules of engagement\\n\\nThis is an authorised exercise against a system FileHub controls. Reach the\\nobjective and stop — FileHub is paying for proof of impact, not for damage.\\nLeave stored data intact, and stay inside the scope above.\\n\\nFileHub has not released the application\'s source code for this engagement.\\nWork from what the running system tells you.\\n\\n## Objective\\n\\nFileHub\'s product page promises that a file uploaded by one account is readable\\nonly by that account. FileHub\'s own engineers no longer believe it.\\n\\nDisprove the promise: retrieve the contents of a file belonging to an account\\nthat is not yours. The administrator keeps stored credentials among their\\nprivate files, and recovering that content is what FileHub will accept as proof\\nof impact. Submit it below to close the engagement.\\n\\n## Deliverable\\n\\nFileHub wants a record of how you got there, not only the result. Log each\\nrequest that moved the assessment forward in the Notes panel, and export the\\nsession when you are done.\\n"},"headers":[],"relativePath":"challenge/door-is-open/index.md","filePath":"challenge/door-is-open/index.md"}'),i={name:"challenge/door-is-open/index.md"};function s(r,e,l,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="need-to-know" tabindex="-1">Need to Know <a class="header-anchor" href="#need-to-know" aria-label="Permalink to “Need to Know”">​</a></h1><p><strong>Client:</strong> FileHub, a file-sharing service used by small teams. <strong>Engagement:</strong> Black-box assessment of the FileHub web application.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope: the FileHub application served at this origin and every HTTP endpoint it exposes.</p><p>FileHub has issued you one account for this engagement — username <code>guest</code>, password <code>guest</code>. It is an ordinary account with no elevated rights, and it is the only credential you have been given.</p><p>Out of scope: the hosting platform, other engagements, and denial of service.</p><h2 id="rules-of-engagement" tabindex="-1">Rules of engagement <a class="header-anchor" href="#rules-of-engagement" aria-label="Permalink to “Rules of engagement”">​</a></h2><p>This is an authorised exercise against a system FileHub controls. Reach the objective and stop — FileHub is paying for proof of impact, not for damage. Leave stored data intact, and stay inside the scope above.</p><p>FileHub has not released the application&#39;s source code for this engagement. Work from what the running system tells you.</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>FileHub&#39;s product page promises that a file uploaded by one account is readable only by that account. FileHub&#39;s own engineers no longer believe it.</p><p>Disprove the promise: retrieve the contents of a file belonging to an account that is not yours. The administrator keeps stored credentials among their private files, and recovering that content is what FileHub will accept as proof of impact. Submit it below to close the engagement.</p><h2 id="deliverable" tabindex="-1">Deliverable <a class="header-anchor" href="#deliverable" aria-label="Permalink to “Deliverable”">​</a></h2><p>FileHub wants a record of how you got there, not only the result. Log each request that moved the assessment forward in the Notes panel, and export the session when you are done.</p>',14)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
